package com.atelier.tasks.exception;
import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler {
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException ex){Map<String,String> fields=new LinkedHashMap<>();ex.getBindingResult().getFieldErrors().forEach(e->fields.putIfAbsent(e.getField(),e.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("status",400,"error","Validation failed","message","Please check the submitted fields","fields",fields,"timestamp",Instant.now()));}
 @ExceptionHandler(org.springframework.http.converter.HttpMessageNotReadableException.class) ResponseEntity<?> malformed(Exception ex){return ResponseEntity.badRequest().body(Map.of("status",400,"error","Bad request","message","The request body is malformed or contains an unsupported value","timestamp",Instant.now()));}
 @ExceptionHandler(ResponseStatusException.class) ResponseEntity<?> status(ResponseStatusException ex){return ResponseEntity.status(ex.getStatusCode()).body(Map.of("status",ex.getStatusCode().value(),"error",HttpStatus.valueOf(ex.getStatusCode().value()).getReasonPhrase(),"message",Objects.requireNonNullElse(ex.getReason(),"Request failed"),"timestamp",Instant.now()));}
 @ExceptionHandler(org.springframework.dao.DataIntegrityViolationException.class) ResponseEntity<?> conflict(Exception ex){return ResponseEntity.status(409).body(Map.of("status",409,"error","Conflict","message","That value conflicts with an existing record","timestamp",Instant.now()));}
 @ExceptionHandler(Exception.class) ResponseEntity<?> unexpected(Exception ex){return ResponseEntity.status(500).body(Map.of("status",500,"error","Internal server error","message","The request could not be completed","timestamp",Instant.now()));}
}
